<?php
declare(strict_types=1);namespace Essivery\Partner\Controllers;
use Essivery\Api\Core\Auth;use Essivery\Api\Core\Request;use Essivery\Api\Core\Response;use Essivery\Api\Services\AuditService;use Essivery\Partner\Domain\PartnerContext;use Essivery\Partner\Repositories\PartnerDeliveryRepository;use Essivery\Partner\Repositories\PartnerDocumentRepository;use Essivery\Partner\Services\PartnerDeliveryService;use Essivery\Partner\Services\PartnerSetupService;
final class PartnerDeliveryController{public function __construct(private array$c){}public function show(Request$r):never{Response::success($this->service()->get($this->context($r)),200,['requestId'=>$r->requestId]);}public function update(Request$r):never{$auth=Auth::context($r);$audit=new AuditService($this->pdo());$value=$this->service()->update($this->context($r),$r->body,function($m)use($audit,$auth,$r){$safe=['vehicleType'=>$m['vehicleType'],'vehicleOwnership'=>$m['vehicleOwnership'],'registrationPresent'=>$m['registrationPresent']];$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.delivery_updated','partner_setup_application',null,$r->requestId,$safe);if($m['completed'])$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.delivery_completed','partner_setup_application',null,$r->requestId,$safe);if($m['vehicleChanged'])$audit->record((int)$auth['user_id'],(int)$auth['identity_id'],'partner_setup.delivery_vehicle_changed','partner_setup_application',null,$r->requestId,$safe);});Response::success($value,200,['requestId'=>$r->requestId]);}private function service():PartnerDeliveryService{$pdo=$this->pdo();$defs=$this->c['partner']['setup']??require dirname(__DIR__).'/config/setup.php';return new PartnerDeliveryService($pdo,new PartnerDeliveryRepository($pdo),new PartnerDocumentRepository($pdo),new PartnerSetupService($pdo,$defs));}private function context(Request$r):PartnerContext{return$r->attributes['partnerContext'];}private function pdo():\PDO{return$this->c['database']->connection();}}

